CREATE TABLE `article_relations` (`from_id` INT NOT NULL, `to_id` INT NOT NULL, PRIMARY KEY (`from_id`,`to_id`), CONSTRAINT `article_relations_from_id_fkey` FOREIGN KEY (`from_id`) REFERENCES `articles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `article_relations_to_id_fkey` FOREIGN KEY (`to_id`) REFERENCES `articles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;